};

/**
 * @method
 * @name scwin.goSearchSW
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goSearchSW = async function () {
    /* sdd-asis-lifecycle:begin goSearchSW — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const swObj = (document.swForm || { elements: [] });
    swObj.action = "/discls/disclosureCommon.do";
    $c.util.getComponent('dma_goSearchSWReq').set('method', "searchCommonPop");
    $c.util.getComponent('dma_goSearchSWReq').set('searchYn', "Y");
    await scwin.tx_goSearchSW();
    /* sdd-asis-lifecycle:end */
};


